package app.manga.user;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="users") public class AppUser {@Id private UUID id;@Column(nullable=false,unique=true,length=254) private String email;@Column(name="password_hash",nullable=false,length=100)private String passwordHash;@Column(name="display_name",nullable=false,length=100)private String displayName;@Column(nullable=false,length=20)private String role="USER";@Column(name="created_at",nullable=false)private Instant createdAt=Instant.now();@Column(name="updated_at",nullable=false)private Instant updatedAt=Instant.now();protected AppUser(){}public AppUser(String email,String hash,String name){this.id=UUID.randomUUID();this.email=email;this.passwordHash=hash;this.displayName=name;}public UUID getId(){return id;}public String getEmail(){return email;}public String getPasswordHash(){return passwordHash;}public String getDisplayName(){return displayName;}public String getRole(){return role;}}
